const bike=document.createElement('div');bike.innerHTML='<svg viewBox="0 0 40 65" width="36" height="56"><rect x="13" y="0" width="14" height="22" rx="5" fill="#282c2c"/><rect x="13" y="43" width="14" height="22" rx="5" fill="#282c2c"/><path d="M9 20 Q20 10 31 20 L27 47 H13 Z" fill="'+color+'" stroke="#383b39" stroke-width="2"/><path d="M3 19 H37" stroke="#77796a" stroke-width="4"/><circle cx="20" cy="29" r="8" fill="'+color+'" stroke="#383b39"/><path d="M11 37 L6 48 M29 37 L34 48" stroke="#687b8e" stroke-width="5"/></svg>';bike.style.cssText='position:absolute;left:140px;top:175px;z-index:3';board.appendChild(bike);
