function activateKartPower(){
const r=arcadeRace;if(!r?.kartDemo||arcadeFinished||r.powerCooldown>0)return;
r.powerCooldown=6;r.powerTime=3;r.shield=3;
for(const node of r.powerEffects||[])node.remove();r.powerEffects=[];
const board=document.querySelector('#arcade-board');
if(r.powerKind==='star'){const bubble=document.createElement('div');bubble.style.cssText='position:absolute;width:90px;height:100px;border:5px solid #83dce8;border-radius:50%;background:#83dce833;box-shadow:0 0 18px #f4d44d;pointer-events:none;z-index:4';board.appendChild(bubble);r.powerEffects.push(bubble)}
else for(let i=0;i<5;i++){const effect=document.createElement('div');effect.textContent=r.powerKind==='fire'?'🔥':r.powerKind==='lightning'?'⚡':'💨';effect.style.cssText='position:absolute;font-size:30px;pointer-events:none;z-index:4;text-shadow:0 0 8px '+(r.powerKind==='fire'?'#edaa55':'#fff0a2');board.appendChild(effect);r.powerEffects.push(effect)}

const fire=r.powerKind==='fire',lightning=r.powerKind==='lightning',star=r.powerKind==='star';
r.distance+=lightning?9:fire?5:star?4:10;
if(fire||lightning||star)for(const rival of r.traffic){rival.stunned=3;rival.y=-80-Math.random()*150;rival.distance=Math.max(0,(rival.distance||0)-5);rival.button.style.opacity='.4'}
r.powerMessage=fire?'🔥 Fire spin-out!':lightning?'⚡ Lightning dodge + speed!':star?'🌟 Force field clears your way!':'🏁 Super racing boost!';
sound('success');
}
function updateKartPowerVisuals(r){
for(const [i,node] of (r.powerEffects||[]).entries()){if(r.powerTime<=0){node.hidden=true;continue}const elapsed=3-r.powerTime;
if(r.powerKind==='star'){node.style.left=(15+r.lane*90)+'px';node.style.top='133px';node.style.transform='scale('+(1+Math.sin(elapsed*8)*.07)+')'}
else if(r.powerKind==='fire'){node.style.left=(40+r.lane*90+(i-2)*12)+'px';node.style.top=(145-((elapsed*140+i*36)%210))+'px';node.style.transform='scale('+(1+(i%2)*.3)+')'}
else{node.style.left=(30+r.lane*90+(i%2?38:-12))+'px';node.style.top=(135+((elapsed*150+i*25)%75))+'px';node.style.transform='rotate('+(i%2?15:-15)+'deg)'}}
for(const rival of r.traffic)rival.button.style.transform=rival.stunned>0?'rotate('+((3-rival.stunned)*480)+'deg)':'none';
}
