let strokes=[],ink='#53564c',drawing=false;const paintCanvas=document.querySelector('#painting'),paintCtx=paintCanvas.getContext('2d');
function renderStrokes(ctx,art){for(const stroke of art){ctx.strokeStyle=stroke.color;ctx.lineWidth=4;ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();stroke.points.forEach((point,i)=>i?ctx.lineTo(...point):ctx.moveTo(...point));if(stroke.points.length===1){ctx.lineTo(stroke.points[0][0]+.1,stroke.points[0][1]+.1)}ctx.stroke()}}
